}

define( 'AGUD_ITEMS_PER_PAGE', 100 );
define( 'AGUD_AUTHOR_PAGE_ARG', 'agud_author_page' );
define( 'AGUD_ATTACHMENT_PAGE_ARG', 'agud_attachment_page' );
define( 'AGUD_CATEGORY_PAGE_ARG', 'agud_category_page' );
define( 'AGUD_TAG_PAGE_ARG', 'agud_tag_page' );

add_action(
	'admin_menu',
	function () {
		add_management_page(
			__( 'Auto-Generated URLs', 'autogenerated-urls' ),
			__( 'Auto URLs', 'autogenerated-urls' ),
