add_filter( 'plugin_action_links_' . plugin_basename( __FILE__ ), 'agud_plugin_action_links' );

/**
 * Add a shortcut to the plugin's Tools page.
 *
 * @param array $links Existing plugin action links.
 * @return array Filtered plugin action links.
 */
function agud_plugin_action_links( array $links ): array {
	$view_urls_link = '<a href="' . esc_url( admin_url( 'tools.php?page=auto-generated-urls' ) ) . '">' . esc_html__( 'View URLs', 'autogenerated-urls' ) . '</a>';

	return array( 'agud-view-urls' => $view_urls_link ) + $links;
}

/**
 * Render the Auto-Generated URLs admin page.
 */
function agud_display_page(): void {
	echo '<div class="wrap"><h1>' . esc_html__( 'Auto-Generated URLs', 'autogenerated-urls' ) . '</h1>';
	echo '<p class="description">' . esc_html__( 'Common WordPress URLs collected for review and testing. Click any URL to open it, or use the copy button.', 'autogenerated-urls' ) . '</p>';
	echo '<style>
		.agud-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(420px,1fr));gap:20px;margin-top:20px}
		.agud-card{background:#fff;border:1px solid #c3c4c7;border-radius:4px;padding:16px 20px}
		.agud-card h2{margin:0 0 10px;font-size:14px}
		.agud-count{font-size:.8em;font-weight:400;color:#50575e}
		.agud-card ul{margin:0}
		.agud-card li{margin:6px 0;line-height:1.5;display:flex;align-items:center;gap:6px;flex-wrap:wrap}
		.agud-card li strong{white-space:nowrap}
		.agud-card .tablenav{margin:10px 0 0}
		.agud-empty{color:#646970;font-style:italic;margin:0}
		.agud-copy{background:#f6f7f7;border:1px solid #c3c4c7;border-radius:4px;padding:2px 8px;font-size:12px;cursor:pointer;color:#2271b1;white-space:nowrap}
		.agud-copy:hover{background:#f0f0f1;border-color:#8c8f94}
		.agud-copy.copied{color:#00a32a}
		.agud-search{margin:20px 0}
		.agud-card.agud-hidden{display:none}
	</style>';
	echo '<div class="agud-search"><input type="search" class="agud-filter" placeholder="' . esc_attr__( 'Filter URLs…', 'autogenerated-urls' ) . '" style="width:100%;max-width:400px" /></div>';
	echo '<script>
		(function(){
			var input=document.querySelector(".agud-filter");
			if(!input)return;
			var cards=document.querySelectorAll(".agud-card");
			input.addEventListener("input",function(){
				var q=this.value.toLowerCase().trim();
				cards.forEach(function(card){
					if(!q){card.classList.remove("agud-hidden");return;}
					var text=card.textContent.toLowerCase();
					card.classList.toggle("agud-hidden",text.indexOf(q)===-1);
				});
			});
		})();
	</script>';
	echo '<div class="agud-grid">';
	foreach ( agud_get_page_sections() as $section ) {
		agud_section( $section['title'], $section['urls'], $section['total'], $section['page'], $section['query_arg'] );
	}
	echo '</div>';
	echo '<script>
		(function(){
			document.addEventListener("click",function(e){
				var btn=e.target.closest(".agud-copy");
				if(!btn)return;
				e.preventDefault();
				var url=btn.getAttribute("data-url");
				navigator.clipboard.writeText(url).then(function(){
					btn.textContent="' . esc_js( __( 'Copied!', 'autogenerated-urls' ) ) . '";
					btn.classList.add("copied");
					setTimeout(function(){btn.textContent="' . esc_js( __( 'Copy', 'autogenerated-urls' ) ) . '";btn.classList.remove("copied");},2000);
				});
			});
		})();
	</script>';
	echo '</div>';
}

/**
 * Get the requested pagination page for a section.
 *
 * @param string $query_arg Query argument name for the section.
 * @return int Current page, with a minimum value of one.
 */
function agud_get_current_page( string $query_arg ): int {
	// phpcs:ignore WordPress.Security.NonceVerification.Recommended, WordPress.Security.ValidatedSanitizedInput.MissingUnslash, WordPress.Security.ValidatedSanitizedInput.InputNotSanitized -- This read-only pagination value is unslashed and validated below.
	$raw_page = $_GET[ $query_arg ] ?? 1;
	$page     = is_scalar( $raw_page ) ? (int) sanitize_text_field( wp_unslash( (string) $raw_page ) ) : 1;

	return max( 1, $page );
}

/**
 * Collect the ordered section data for the admin page.
