	$author_total     = 0;
	$attachment_total = 0;
	$category_total   = 0;
	$tag_total        = 0;

	$author_page     = agud_get_current_page( AGUD_AUTHOR_PAGE_ARG );
	$attachment_page = agud_get_current_page( AGUD_ATTACHMENT_PAGE_ARG );
	$category_page   = agud_get_current_page( AGUD_CATEGORY_PAGE_ARG );
	$tag_page        = agud_get_current_page( AGUD_TAG_PAGE_ARG );

	$author_urls     = agud_get_author_urls( $author_page, $author_total );
	$attachment_urls = agud_get_attachment_urls( $attachment_page, $attachment_total );
	$category_urls   = agud_get_taxonomy_urls( 'category', $category_page, $category_total );
	$tag_urls        = agud_get_taxonomy_urls( 'post_tag', $tag_page, $tag_total );

