/**
 * Render one URL section and its pagination controls.
 *
 * @param string $title      Section heading.
 * @param array  $urls       Labels mapped to URLs.
 * @param int    $total      Total items available.
 * @param int    $page       Current page.
 * @param string $query_arg  Query argument name for pagination, or empty string.
 */
function agud_section( string $title, array $urls, int $total = 0, int $page = 1, string $query_arg = '' ): void {
	echo '<div class="agud-card">';
	$heading = '<h2>' . esc_html( $title );
	if ( $total > 0 ) {
		$heading .= ' <span class="agud-count">' . esc_html(
			sprintf(
				/* translators: %d: Total item count. */
				_n( '%d item', '%d items', $total, 'autogenerated-urls' ),
				$total
			)
		) . '</span>';
	}
	$heading .= '</h2>';
	echo wp_kses_post( $heading );
	if ( empty( $urls ) ) {
		echo '<p class="agud-empty">' . esc_html__( 'None found.', 'autogenerated-urls' ) . '</p>';
		echo '</div>';
		return;
	}
	echo '<ul>';
	foreach ( $urls as $name => $url ) {
		if ( ! is_string( $url ) || '' === $url ) {
			continue;
		}
		echo '<li><strong>' . esc_html( $name ) . ':</strong> <a href="' . esc_url( $url ) . '" target="_blank" rel="noopener noreferrer">' . esc_html( $url ) . '</a>';
		echo ' <button type="button" class="agud-copy" data-url="' . esc_attr( $url ) . '">' . esc_html__( 'Copy', 'autogenerated-urls' ) . '</button></li>';
	}
	echo '</ul>';

	$page_count = (int) ceil( $total / AGUD_ITEMS_PER_PAGE );
	if ( $page_count > 1 && '' !== $query_arg ) {
		echo '<div class="tablenav"><div class="tablenav-pages">';
		echo wp_kses_post(
			paginate_links(
				array(
					'base'      => add_query_arg( $query_arg, '%#%', menu_page_url( 'auto-generated-urls', false ) ),
					'current'   => $page,
					'total'     => $page_count,
					'type'      => 'list',
					'prev_text' => esc_html__( 'Previous', 'autogenerated-urls' ),
					'next_text' => esc_html__( 'Next', 'autogenerated-urls' ),
				)
			)
		);
		echo '</div></div>';
	}
	echo '</div>';
}

/**
 * Collect paginated author archive URLs.
 *
 * @param int $page  Current page.
 * @param int $total Total matching authors, passed by reference.
 * @return array Labels mapped to author archive URLs.
 */
function agud_get_author_urls( int $page = 1, int &$total = 0 ): array {
	$urls    = array();
	$query   = new WP_User_Query(
		array(
			'capability'  => 'edit_posts',
			'number'      => AGUD_ITEMS_PER_PAGE,
			'offset'      => ( max( 1, $page ) - 1 ) * AGUD_ITEMS_PER_PAGE,
			'count_total' => true,
		)
	);
	$authors = $query->get_results();
	$total   = (int) $query->get_total();
	foreach ( $authors as $author ) {
		/* translators: 1: Author display name. 2: Author ID. */
		$urls[ sprintf( esc_html__( '%1$s (#%2$d)', 'autogenerated-urls' ), $author->display_name, (int) $author->ID ) ] = get_author_posts_url( $author->ID );
	}
	return $urls;
}

/**
 * Collect paginated media attachment URLs.
 *
 * @param int $page  Current page.
 * @param int $total Total matching attachments, passed by reference.
 * @return array Labels mapped to attachment URLs.
 */
function agud_get_attachment_urls( int $page = 1, int &$total = 0 ): array {
	$urls = array();

	$attachment_ids = get_posts(
		array(
			'post_type'      => 'attachment',
			'post_status'    => 'inherit',
			'posts_per_page' => AGUD_ITEMS_PER_PAGE,
			'paged'          => max( 1, $page ),
			'orderby'        => 'ID',
			'order'          => 'ASC',
			'fields'         => 'ids',
		)
	);

	$attachment_counts = wp_count_posts( 'attachment' );
	$total             = isset( $attachment_counts->inherit ) ? (int) $attachment_counts->inherit : 0;

	foreach ( $attachment_ids as $attachment_id ) {
		$attachment_id = (int) $attachment_id;
		$title         = get_the_title( $attachment_id );
		$link          = get_attachment_link( $attachment_id );
		if ( is_string( $link ) && '' !== $link ) {
			/* translators: 1: Attachment title. 2: Attachment ID. */
			$urls[ sprintf( esc_html__( '%1$s (#%2$d)', 'autogenerated-urls' ), $title, $attachment_id ) ] = $link;
		}
	}

	return $urls;
}

/**
 * Collect paginated taxonomy archive URLs.
 *
 * @param string $taxonomy Taxonomy name.
 * @param int    $page     Current page.
 * @param int    $total    Total matching terms, passed by reference.
 * @return array Labels mapped to term archive URLs.
 */
function agud_get_taxonomy_urls( string $taxonomy, int $page = 1, int &$total = 0 ): array {
	$urls = array();

	$terms = get_terms(
		array(
			'taxonomy'   => $taxonomy,
			'hide_empty' => true,
			'number'     => AGUD_ITEMS_PER_PAGE,
			'offset'     => ( max( 1, $page ) - 1 ) * AGUD_ITEMS_PER_PAGE,
		)
	);
	if ( is_wp_error( $terms ) ) {
		$terms = array();
	}
	$term_count = wp_count_terms(
		array(
			'taxonomy'   => $taxonomy,
			'hide_empty' => true,
		)
	);
	$total      = is_wp_error( $term_count ) ? 0 : (int) $term_count;

	$label = 'category' === $taxonomy ? __( 'Category', 'autogenerated-urls' ) : __( 'Tag', 'autogenerated-urls' );
	foreach ( $terms as $term ) {
		$link = get_term_link( $term );
		if ( ! is_wp_error( $link ) && is_string( $link ) && '' !== $link ) {
			/* translators: 1: Taxonomy label. 2: Term name. 3: Term ID. */
			$urls[ sprintf( esc_html__( '%1$s: %2$s (%3$d)', 'autogenerated-urls' ), $label, $term->name, (int) $term->term_id ) ] = $link;
		}
	}

	return $urls;
}

/**
 * Collect published year and month archive URLs.
 *
 * @return array Labels mapped to date archive URLs.
 */
function agud_get_date_archive_urls(): array {
	$urls = array();

	global $wpdb;

	// phpcs:ignore WordPress.DB.DirectDatabaseQuery.DirectQuery, WordPress.DB.DirectDatabaseQuery.NoCaching -- A single grouped read avoids the previous N+1 archive queries; results are request-local.
	$pairs = $wpdb->get_results(
		"SELECT DISTINCT YEAR(post_date) AS year_num, MONTH(post_date) AS month_num
    FROM {$wpdb->posts}
    WHERE post_type = 'post' AND post_status = 'publish'
    ORDER BY year_num DESC, month_num DESC"
	);

	$seen_years = array();
	foreach ( $pairs as $pair ) {
		$year  = (int) $pair->year_num;
		$month = (int) $pair->month_num;

		if ( ! isset( $seen_years[ $year ] ) ) {
			/* translators: %d: Four-digit archive year. */
			$urls[ sprintf( esc_html__( 'Year: %d', 'autogenerated-urls' ), $year ) ] = get_year_link( $year );
			$seen_years[ $year ] = true;
		}

		if ( $month > 0 && $month <= 12 ) {
			$month_name = wp_date( 'F', gmmktime( 0, 0, 0, $month, 1, $year ) );
			/* translators: 1: Month name. 2: Four-digit archive year. */
			$urls[ sprintf( esc_html__( 'Month: %1$s %2$d', 'autogenerated-urls' ), $month_name, $year ) ] = get_month_link( $year, $month );
		}
	}

	return $urls;
}

/**
 * Collect archive URLs for public custom post types.
 *
 * @return array Labels mapped to custom post type archive URLs.
 */
function agud_get_cpt_archive_urls(): array {
	$urls       = array();
	$post_types = get_post_types(
		array(
			'public'      => true,
			'has_archive' => true,
		),
		'objects'
	);
	foreach ( $post_types as $pt ) {
		if ( in_array( $pt->name, array( 'post', 'page' ), true ) ) {
			continue;
		}

		$link = get_post_type_archive_link( $pt->name );
		if ( is_string( $link ) && '' !== $link ) {
			/* translators: 1: Post type label. 2: Post type name. */
			$urls[ sprintf( esc_html__( 'CPT Archive: %1$s (%2$s)', 'autogenerated-urls' ), $pt->labels->name, $pt->name ) ] = $link;
		}
	}

	return $urls;
}
